@pytest.fixture(autouse=True)
def clean_tables():
    """Truncate the tables under test before every test so cases don't bleed into each other."""
    with m.get_db_conn() as conn:
        # seen_jobs/seen_content_hashes are the dedup ledgers: without truncating them, a test that
        # ingests a posting makes every later test using the same company/title silently take the
        # "already in the pipeline" branch instead of the path it meant to exercise.
        for table in ("crm_outbox", "sheet_row_map", "company_cooldown", "company_identities",
                      "jobs", "followup_sequencer_log", "followup_queue_snapshot", "gmail_drafts", "seen_jobs",
                      "seen_content_hashes", "jd_term_yield", "job_link_status", "warm_screen_memo",
                      # died_roles is permanent by design, so a row left behind by one test would
                      # silently suppress a role in every later one.
                      "died_roles", "owed_dismissals", "referral_asks",
                      "command_usage"):
            conn.execute(f"DELETE FROM {table}")
        # search_filters is shared config, so only the ghost-burial switch is reset: every test
        # starts with it unset (= OFF, the production state) and opts in through _set_ghost_burial.
        conn.execute("DELETE FROM search_filters WHERE key = 'auto_bury_ghosted_applications'")
        conn.commit()
    # Module-global name cache: a Sent lookup in one test must not answer for the next.
    m._SENT_NAME_CACHE.clear()
    # /e, /eh and /letter cache their live posting check per sheet_uuid for 10 minutes.
    m._POSTING_CHECK_CACHE.clear()
    m._OPEN_FOLLOWUPS_CACHE.update(owed=None, at=None)
    m._OPEN_FOLLOWUPS_BUILD.update(running=False, error=None)
    yield


_LOOPBACK_HOSTS = ("127.0.0.1", "::1", "localhost")


@pytest.fixture(autouse=True)
def _no_real_network_guard(monkeypatch):
    """A test that opens a non-loopback socket fails, naming the address. Code under test often
    catches the connection error and falls back, so the failure is also raised at teardown from a
    recorded list, not only inside the call. Unix sockets (str addresses) stay allowed."""
    attempts = []
    real_connect = socket.socket.connect

    def guarded(sock, address):
        if isinstance(address, tuple) and address[0] not in _LOOPBACK_HOSTS:
            attempts.append(address)
            raise OSError(f"real network connect blocked by test guard: {address!r}")
        return real_connect(sock, address)

    monkeypatch.setattr(socket.socket, "connect", guarded)
    yield attempts
    assert not attempts, f"test made real outbound connection(s): {attempts}"


def test_no_real_network_guard_reports_non_local_and_allows_loopback(_no_real_network_guard):
    attempts = _no_real_network_guard
    with socket.socket() as s:
        with pytest.raises(OSError, match="203.0.113.9"):
            s.connect(("203.0.113.9", 443))
    assert attempts == [("203.0.113.9", 443)]
    attempts.clear()  # reported and checked; clear so this test's own teardown assertion passes
    listener = socket.socket()
    listener.bind(("127.0.0.1", 0))
    listener.listen(1)
    try:
        with socket.socket() as c:
            c.connect(listener.getsockname())
    finally:
        listener.close()
    assert attempts == []


