    bury_boundary = (
        date.fromisoformat(_SEQ_BUMP_DATE) + timedelta(days=m.FOLLOWUP_BURY_DAYS)
    ).isoformat()
    assert [(p["sheet_uuid"], p["next_followup"]) for p in snoozes] == [("app-0", bury_boundary)]
    assert _logged_uuids() == {"app-0"}


