def _refs_env(monkeypatch):
    """Clean slate for the references row, plus capture of what /refs writes to System_Config.
    search_filters is not truncated by clean_tables, so the row is removed here."""
    with m.get_db_conn() as conn:
        conn.execute("DELETE FROM search_filters WHERE key = ?", (pipeline_utils.REFERENCES_FILTER_KEY,))
        conn.commit()
    sent, sheet_writes = [], []
    monkeypatch.setattr(m, "send_telegram_message", lambda cid, t, *a, **k: sent.append(t) or 1)
    monkeypatch.setattr(m, "crm_post", lambda payload, **kw: sheet_writes.append(payload))
    return sent, sheet_writes


def test_refs_add_then_refs_reads_it_back(monkeypatch):
    sent, _ = _refs_env(monkeypatch)
    _dispatch("/refs add Dana Reed | dana@acme.com | 313-555-0100 | Work | 2 | Acme | Detroit, Michigan")
    _dispatch("/refs")
    assert "<code>dana@acme.com</code>" in sent[-1]
    assert "<code>313-555-0100</code>" in sent[-1]
    assert "Acme" in sent[-1] and "Detroit, Michigan" in sent[-1]


def test_refs_survive_a_redeploy_that_wipes_the_disk(monkeypatch):
    """Render's disk is not durable across a fresh deploy, and the references are deliberately
    absent from the repo. So the System_Config row /refs writes IS the copy that matters. Feed
    exactly that written value back through the boot-time hydration path, with the local row
    gone, and /refs must still print it."""
    sent, sheet_writes = _refs_env(monkeypatch)
    _dispatch("/refs add Dana Reed | dana@acme.com | 313-555-0100")
    written = [p for p in sheet_writes if p.get("action") == "update_system_config"
               and p.get("key") == pipeline_utils.REFERENCES_FILTER_KEY]
    assert written, "/refs add never reached the System_Config sheet"

    with m.get_db_conn() as conn:  # the redeploy
        conn.execute("DELETE FROM search_filters WHERE key = ?", (pipeline_utils.REFERENCES_FILTER_KEY,))
        conn.commit()

    class _SheetResp:
        status_code = 200
        @staticmethod
        def json():
            return {"filters": {pipeline_utils.REFERENCES_FILTER_KEY: written[-1]["value"]}}
    monkeypatch.setattr(m, "crm_get", lambda params, **kw: _SheetResp())
    m.hydrate_filters_from_sheets()

    _dispatch("/refs")
    assert "<code>dana@acme.com</code>" in sent[-1]


def test_refs_add_with_the_same_name_replaces_and_remove_drops_by_number(monkeypatch):
    sent, _ = _refs_env(monkeypatch)
    _dispatch("/refs add Dana Reed | dana@acme.com | 313-555-0100")
    _dispatch("/refs add Lee Park | lee@acme.com | 313-555-0101")
    _dispatch("/refs add dana reed | dana@newco.com | 313-555-0199")  # corrected details
    _dispatch("/refs")
    assert "dana@acme.com" not in sent[-1] and "dana@newco.com" in sent[-1]
    assert "References (2)" in sent[-1]

    _dispatch("/refs remove 1")  # Lee is #1 now - the corrected Dana was re-appended
    assert "lee@acme.com" not in sent[-1] and "dana@newco.com" in sent[-1]


def test_refs_add_with_a_bad_email_saves_nothing(monkeypatch):
    sent, sheet_writes = _refs_env(monkeypatch)
    _dispatch("/refs add Dana Reed | not-an-email | 313-555-0100")
    assert "Email looks wrong" in sent[-1]
    assert sheet_writes == []
    assert m.get_filter(pipeline_utils.REFERENCES_FILTER_KEY) is None


# ==============================================================================
# Outbox under a broken CRM secret: hold the writes, do not burn them
# ==============================================================================

def _crm_answers(monkeypatch, body):
    """Point the REAL log_to_sheets_crm at a webhook that answers 200 with `body`, the way Apps
    Script answers everything - including its own Unauthorized."""
    class _Resp:
        status_code = 200
        text = json.dumps(body)
        def json(self):
            return body
    monkeypatch.setattr(m, "CRM_WEBHOOK_URL", "https://script.google.com/fake")
    monkeypatch.setattr(m, "crm_post", lambda payload, **kw: _Resp())
    monkeypatch.setattr(m.time, "sleep", lambda *_a, **_k: None)


def _outbox_rows():
    with m.get_db_conn() as conn:
        return conn.execute("SELECT retry_count, status FROM crm_outbox ORDER BY id").fetchall()


@pytest.fixture
def _auth_reset():
    m._CRM_AUTH_BACKOFF["until"] = 0.0
    with m.get_db_conn() as conn:
        conn.execute("DELETE FROM system_alerts WHERE alert_key = 'crm_write_unauthorized'")
        conn.commit()
    yield
    m._CRM_AUTH_BACKOFF["until"] = 0.0


def test_a_broken_secret_holds_writes_and_they_land_once_it_is_fixed(monkeypatch, _auth_reset):
    """2026-10-07: the secret broke around 13:00, Kevin's /warm and /x at 15:38 each burned 10
    retries inside a minute and went FAILED - never to replay - while the bot had already said
    "Moved to Warm". Drives the real outbox pass and the real log_to_sheets_crm through 15 passes
    of Unauthorized, then fixes the secret and checks the same writes reach the sheet."""
    alerts = _capture_alerts(monkeypatch)
    m.enqueue_crm_payload({"action": "update_status", "sheet_uuid": "u-sun", "new_tab": "Tetiana Warm"})
    m.enqueue_crm_payload({"action": "update_status", "sheet_uuid": "u-apex", "new_tab": "Died"})

    _crm_answers(monkeypatch, {"status": "error", "message": "Unauthorized"})
    for _ in range(15):
        m._CRM_AUTH_BACKOFF["until"] = 0.0  # skip the 60s wait between passes
        m.process_crm_outbox_batch(inter_job_sleep=0)
    assert _outbox_rows() == [(0, "PENDING"), (0, "PENDING")], "an auth outage spent the retry budget"
    assert len([a for a in alerts if "Unauthorized" in a]) == 1, "the held writes re-alerted every pass"

    _crm_answers(monkeypatch, {"status": "success"})
    m._CRM_AUTH_BACKOFF["until"] = 0.0
    m.process_crm_outbox_batch(inter_job_sleep=0)
    assert _outbox_rows() == [], "the held writes did not land after the secret was fixed"


def test_an_auth_rejection_backs_off_instead_of_hammering_apps_script(monkeypatch, _auth_reset):
    _capture_alerts(monkeypatch)
    calls = []
    class _Resp:
        status_code = 200
        def json(self):
            return {"status": "error", "message": "Unauthorized"}
    monkeypatch.setattr(m, "CRM_WEBHOOK_URL", "https://script.google.com/fake")
    monkeypatch.setattr(m, "crm_post", lambda payload, **kw: calls.append(payload) or _Resp())
    monkeypatch.setattr(m.time, "sleep", lambda *_a, **_k: None)
    m.enqueue_crm_payload({"action": "update_status", "sheet_uuid": "a"})
    m.enqueue_crm_payload({"action": "update_status", "sheet_uuid": "b"})

    m.process_crm_outbox_batch(inter_job_sleep=0)
    m.process_crm_outbox_batch(inter_job_sleep=0)  # inside the 60s back-off
    assert len(calls) == 1, "one rejected secret should stop the pass and pause the next one"


def test_crazy_retry_requeues_writes_that_already_gave_up(monkeypatch, _auth_reset):
    """The rows lost before this fix shipped are FAILED on Render's disk. /crazy retry is how
    they come back once the secret is right."""
    with m.get_db_conn() as conn:
        conn.execute("INSERT INTO crm_outbox (payload_json, status, retry_count) VALUES (?, 'FAILED', 10)",
                     ('{"action": "update_status", "sheet_uuid": "u-sun"}',))
        conn.execute("INSERT INTO crm_outbox (payload_json, status, retry_count) VALUES (?, 'FAILED_UNALERTED', 10)",
                     ('{"action": "update_status", "sheet_uuid": "u-apex"}',))
        conn.commit()
    sent = []
    monkeypatch.setattr(m, "send_telegram_message", lambda cid, t, *a, **k: sent.append(t) or 1)

    _dispatch("/crazy retry")
    assert "Re-queued 2" in sent[-1]
    assert _outbox_rows() == [(0, "PENDING"), (0, "PENDING")]

    _crm_answers(monkeypatch, {"status": "success"})
    m.process_crm_outbox_batch(inter_job_sleep=0)
    assert _outbox_rows() == []


# ---- /track: re-route a card's resume track ----

_TRACK_UUID = "3f2b8c1e-5a4d-4e6f-9b7a-1c2d3e4f5a6b"


def _u16(s):
    return len(s.encode("utf-16-le")) // 2


def _entity_text(text, entity):
    """The substring an entity covers, measured the way Telegram measures it (UTF-16 units)."""
    raw = text.encode("utf-16-le")
    start = entity["offset"] * 2
    return raw[start:start + entity["length"] * 2].decode("utf-16-le")


def _track_card():
    """A card as Telegram hands it back in reply_to_message: plain text plus entities, with
    astral-plane emoji (2 UTF-16 units each) ahead of the tag so offset math is actually tested."""
    head = "💼 MMF: NextEnergy\n🏢 CEDAM\n🆔 "
    tag_prefix = f"{_TRACK_UUID} · Tetiana Cold · 🧭 "
    tag = "f|conservative|0,1,2|6"
    tail = "\n\n🔥 Notes after the tag"
    text = head + tag_prefix + tag + tail
    entities = [
        {"type": "bold", "offset": _u16("💼 "), "length": _u16("MMF: NextEnergy")},
        {"type": "code", "offset": _u16(head), "length": _u16(_TRACK_UUID)},
        {"type": "code", "offset": _u16(head + tag_prefix), "length": _u16(tag)},
        {"type": "bold", "offset": _u16(head + tag_prefix + tag + "\n\n🔥 "), "length": _u16("Notes")},
    ]
    return text, entities


def _cache_track_job(track="f", bullet_indices=(0, 1, 2), outreach_template_id=6):
    job = {"employer_name": "CEDAM", "job_title": "MMF: NextEnergy", "track": track,
           "bullet_indices": list(bullet_indices), "tone_mode": "conservative",
           "outreach_template_id": outreach_template_id}
    m.save_job_to_cache("trk001", job, sheet_uuid=_TRACK_UUID)
    return job


def _track_env(monkeypatch):
    sent, edits = [], []
    monkeypatch.setattr(m, "send_telegram_message", lambda cid, text: sent.append(text))
    monkeypatch.setattr(m, "edit_telegram_message_entities",
                        lambda cid, mid, text, entities: edits.append((mid, text, entities)) or True)
    return sent, edits


def test_track_command_reroutes_what_the_next_cv_and_letter_read(monkeypatch):
    """Gemini routed the CEDAM/NextEnergy card to track F (queue and SLA bullets) when the role
    is a research post whose headline duty is a funding web scraper. /track h must change what
    the NEXT /cv and /letter build, not just what /track replies with."""
    _cache_track_job()
    sent, edits = _track_env(monkeypatch)
    card_text, entities = _track_card()

    _dispatch("/track h 9,3,4,0", reply_to_message={"message_id": 77, "text": card_text, "entities": entities})

    job = m.get_job_by_sheet_uuid(_TRACK_UUID)
    assert job["track"] == "h"
    assert job["bullet_indices"] == [9, 3, 4, 0]
    assert job["outreach_template_id"] == track_registry.coerce_outreach_template_id("h", 6)
    assert "Track F → H" in sent[-1]

    # The next /letter: the shared resolver reads the cache.
    _, letter_track = m.resolve_letter_for_job(job, {"sheet_uuid": _TRACK_UUID}, "CEDAM")
    assert letter_track == "h"

    # The next /cv, driven through the real dispatcher.
    compiled = []
    monkeypatch.setattr(m, "compile_resume_pdf",
                        lambda comp, track, bullet_indices, tone_mode: compiled.append((track, bullet_indices)) or b"%PDF")
    monkeypatch.setattr(m, "send_telegram_document", lambda *a, **k: True)
    _dispatch("/cv", reply_to_message={"message_id": 77, "text": card_text, "entities": entities})
    assert compiled == [("h", [9, 3, 4, 0])]


def test_track_command_rewrites_the_card_so_a_deploy_cannot_revert_it(monkeypatch):
    """A deploy wipes the jobs cache and /draft, /e rebuild from the card's 🧭 tag. If /track only
    wrote the cache, the next deploy would silently put the card back on track F."""
    _cache_track_job()
    _, edits = _track_env(monkeypatch)
    card_text, entities = _track_card()

    _dispatch("/track h 9,3,4,0", reply_to_message={"message_id": 77, "text": card_text, "entities": entities})

    assert len(edits) == 1
    message_id, new_text, new_entities = edits[0]
    assert message_id == 77
    routed = m._parse_routing_from_card_text(new_text)
    assert routed["track"] == "h" and routed["bullet_indices"] == [9, 3, 4, 0]
    rebuilt, recovered = m.rebuild_job_from_card({}, new_text)
    assert recovered and rebuilt["track"] == "h"

    # Every span still covers the same words: the title, the uuid, the whole new tag, and the
    # bold word AFTER the tag, whose offset had to move by the tag's length change.
    covered = [_entity_text(new_text, e) for e in new_entities]
    assert covered[0] == "MMF: NextEnergy"
    assert covered[1] == _TRACK_UUID
    assert covered[2] == new_text.split("🧭 ")[1].split("\n")[0]
    assert covered[3] == "Notes"


def test_track_without_bullets_drops_the_old_tracks_indices(monkeypatch):
    """Gemini's indices were chosen from track F's pool. Carried into track H they would pick
    arbitrary bullets, so a bare /track h resets them and shows the pool to choose from."""
    _cache_track_job(bullet_indices=(5, 6, 7))
    sent, _ = _track_env(monkeypatch)
    card_text, entities = _track_card()

    _dispatch("/track h", reply_to_message={"message_id": 77, "text": card_text, "entities": entities})

    assert m.get_job_by_sheet_uuid(_TRACK_UUID)["bullet_indices"] is None
    assert "/track h 9,3,4,0" in sent[-1]


@pytest.mark.parametrize("command", ["/track z", "/track h 99", "/track h 1,99"])
def test_track_rejects_a_bad_letter_or_bullet_without_writing_anything(monkeypatch, command):
    _cache_track_job()
    sent, edits = _track_env(monkeypatch)
    card_text, entities = _track_card()

    _dispatch(command, reply_to_message={"message_id": 77, "text": card_text, "entities": entities})

    job = m.get_job_by_sheet_uuid(_TRACK_UUID)
    assert job["track"] == "f" and job["bullet_indices"] == [0, 1, 2]
    assert edits == []
    assert sent and "⚠️" in sent[-1]


def test_bare_track_shows_the_current_track_without_changing_it(monkeypatch):
    _cache_track_job()
    sent, edits = _track_env(monkeypatch)
    card_text, entities = _track_card()

    _dispatch("/track", reply_to_message={"message_id": 77, "text": card_text, "entities": entities})

    assert "Track F" in sent[-1] and "← current" in sent[-1]
    assert m.get_job_by_sheet_uuid(_TRACK_UUID)["track"] == "f"
    assert edits == []


def test_cv_accepts_tracks_f_through_h(monkeypatch):
    """The /cv regex was [a-e], so `/cv h` matched no handler and did nothing at all."""
    _cache_track_job()
    compiled = []
    monkeypatch.setattr(m, "compile_resume_pdf",
                        lambda comp, track, bullet_indices, tone_mode: compiled.append(track) or b"%PDF")
    monkeypatch.setattr(m, "send_telegram_document", lambda *a, **k: True)
    monkeypatch.setattr(m, "send_telegram_message", lambda *a, **k: None)
    card_text, entities = _track_card()

    _dispatch("/cv h", reply_to_message={"message_id": 77, "text": card_text, "entities": entities})

    assert compiled == ["h"]


# ---- JSearch direct apply link (normalized once, at the fetch boundary) ----

_DAL_LINKEDIN = "https://www.linkedin.com/jobs/view/3900000001"
_DAL_EMPLOYER = "https://careers.acmefab.com/jobs/ops-analyst-441"


def _dal_fetch(monkeypatch, raw_jobs):
    """Push raw JSearch-shaped dicts through the real fetch_single_query_jobs boundary."""
    monkeypatch.setattr(m, "_fetch_jsearch_page_with_retry",
                        lambda api_url, headers, params, query, page: (list(raw_jobs), True))
    monkeypatch.setattr(m, "get_filter", lambda key, default=None: 45 if key == "radius_miles" else default)
    monkeypatch.setattr(m.time, "sleep", lambda s: None)
    return m.fetch_single_query_jobs(("Operations Analyst Troy MI", "http://x", {}))


def _dal_job(**over):
    job = {"job_id": "j1", "employer_name": "Acme Fabrication", "job_title": "Operations Analyst",
           "job_apply_link": _DAL_LINKEDIN, "job_apply_is_direct": False,
           "employer_website": "https://www.acmefab.com"}
    job.update(over)
    return job


def test_direct_apply_link_replaces_a_relist_with_the_flagged_employer_option(monkeypatch):
    job = _dal_job(apply_options=[
        {"publisher": "LinkedIn", "apply_link": _DAL_LINKEDIN, "is_direct": False},
        {"publisher": "Acme", "apply_link": _DAL_EMPLOYER, "is_direct": True},
    ])
    out = _dal_fetch(monkeypatch, [job])[0]

    assert out["job_apply_link"] == _DAL_EMPLOYER
    assert out["job_relist_link"] == _DAL_LINKEDIN


def test_direct_apply_link_keeps_a_link_jsearch_already_marked_direct(monkeypatch):
    job = _dal_job(job_apply_link=_DAL_EMPLOYER, job_apply_is_direct=True, apply_options=[
        {"publisher": "Other", "apply_link": "https://other.example.com/x", "is_direct": True}])
    out = _dal_fetch(monkeypatch, [job])[0]

    assert out["job_apply_link"] == _DAL_EMPLOYER
    assert "job_relist_link" not in out


def test_direct_apply_link_falls_back_to_an_option_on_the_employer_website_domain(monkeypatch):
    job = _dal_job(apply_options=[
        {"publisher": "BeBee", "apply_link": "https://bebee.com/job/abc", "is_direct": False},
        {"publisher": "Acme", "apply_link": "https://jobs.acmefab.com/req/9", "is_direct": False},
    ])
    out = _dal_fetch(monkeypatch, [job])[0]

    assert out["job_apply_link"] == "https://jobs.acmefab.com/req/9"
    assert out["job_relist_link"] == _DAL_LINKEDIN


def test_direct_apply_link_a_lookalike_domain_is_not_the_employer(monkeypatch):
    job = _dal_job(apply_options=[
        {"publisher": "x", "apply_link": "https://notacmefab.com/req/9", "is_direct": False}])
    out = _dal_fetch(monkeypatch, [job])[0]

    assert out["job_apply_link"] == _DAL_LINKEDIN


@pytest.mark.parametrize("options", [
    "not-a-list", None, 7, [], [None, "x", 3],
    [{"apply_link": "https://bebee.com/a", "is_direct": False}],          # no direct, no employer host
    [{"apply_link": None, "is_direct": True}, {"is_direct": True}],       # direct but no link
    [{"apply_link": "acmefab.com/jobs", "is_direct": True}],              # not an http(s) link
], ids=["string", "none", "int", "empty", "junk-entries", "all-relists", "no-link", "not-http"])
def test_direct_apply_link_malformed_or_useless_options_leave_the_job_untouched(monkeypatch, options):
    job = _dal_job(apply_options=options)
    before = dict(job)
    out = _dal_fetch(monkeypatch, [job])[0]

    assert out == before
    assert "job_relist_link" not in out


def test_direct_apply_link_missing_options_key_and_odd_types_do_not_raise(monkeypatch):
    jobs = [_dal_job(), _dal_job(job_apply_link=None, apply_options=[
        {"apply_link": _DAL_EMPLOYER, "is_direct": True}]), _dal_job(employer_website=42)]
    out = _dal_fetch(monkeypatch, jobs)

    assert len(out) == 3
    assert out[0]["job_apply_link"] == _DAL_LINKEDIN
    assert out[1]["job_apply_link"] == _DAL_EMPLOYER and "job_relist_link" not in out[1]


def test_direct_apply_link_never_picks_an_aggregator_relist_even_when_flagged_direct(monkeypatch):
    relist = "https://www.learn4good.com/jobs/view/55"
    job = _dal_job(apply_options=[{"publisher": "L4G", "apply_link": relist, "is_direct": True}])
    out = _dal_fetch(monkeypatch, [job])[0]

    assert out["job_apply_link"] == _DAL_LINKEDIN
    assert "job_relist_link" not in out


def test_direct_apply_link_rescued_relist_job_clears_the_aggregator_link_gate(monkeypatch):
    relist = "https://www.learn4good.com/jobs/view/55"
    raw = _dal_job(job_apply_link=relist, apply_options=[
        {"publisher": "learn4good", "apply_link": relist, "is_direct": False},
        {"publisher": "Acme", "apply_link": _DAL_EMPLOYER, "is_direct": True}])
    control = dict(raw, apply_options=[{"publisher": "learn4good", "apply_link": relist, "is_direct": False}])

    rescued = _dal_fetch(monkeypatch, [raw])[0]
    stuck = _dal_fetch(monkeypatch, [control])[0]

    trace_stuck = m.FunnelTrace()
    m.passes_strict_filter(stuck, trace_stuck)
    assert "aggregator_link" in trace_stuck.reasons        # the gate does fire on the bare relist

    trace_rescued = m.FunnelTrace()
    m.passes_strict_filter(rescued, trace_rescued)
    assert rescued["job_apply_link"] == _DAL_EMPLOYER and rescued["job_relist_link"] == relist
    assert "aggregator_link" not in trace_rescued.reasons


# ---- weekly build-log draft (Sundays 18:00 local, Telegram only) ----

@pytest.fixture
def build_log_env(monkeypatch, capture_sent):
    """Clean pipeline_metrics and inbound_threads (clean_tables does not truncate either), and
    make any outbound HTTP a test failure: the weekly job may only call send_telegram_message."""
    with m.get_db_conn() as conn:
        conn.execute("DELETE FROM pipeline_metrics")
        conn.execute("DELETE FROM inbound_threads")
        conn.commit()

    def _no_http(*a, **k):
        pytest.fail("the weekly build-log job made an HTTP call")
    monkeypatch.setattr(m.requests, "post", _no_http)
    monkeypatch.setattr(m.requests, "get", _no_http)
    yield capture_sent
    # Teardown runs while this test's monkeypatches (a bad DB_PATH, a failing get_db_conn) are
    # still active, so clean through a direct connection to the real test database.
    conn = sqlite3.connect(_TMP_DB_PATH)
    try:
        conn.execute("DELETE FROM pipeline_metrics")
        conn.execute("DELETE FROM inbound_threads")
        conn.commit()
    finally:
        conn.close()


def _seed_week(counts, stale=0):
    """counts: {event_type: n}. Every event gets n in-window rows and `stale` rows 10 days old."""
    with m.get_db_conn() as conn:
        for event, n in counts.items():
            for _ in range(n):
                conn.execute("INSERT INTO pipeline_metrics (event_type, timestamp) "
                             "VALUES (?, datetime('now', '-1 days'))", (event,))
            for _ in range(stale):
                conn.execute("INSERT INTO pipeline_metrics (event_type, timestamp) "
                             "VALUES (?, datetime('now', '-10 days'))", (event,))
        conn.commit()


def _seed_thread(thread_id, label, days_ago):
    with m.get_db_conn() as conn:
        conn.execute("INSERT INTO inbound_threads (thread_id, status_label, state, first_seen) "
                     "VALUES (?, ?, 'open', datetime('now', ?))", (thread_id, label, f"-{days_ago} days"))
        conn.commit()


_BL_WEEK = {"listing_discovered": 37, "ai_screened": 23, m.DOCUMENT_COMPILED_EVENT: 11,
            "gmail_draft_staged": 6, "applied": 4, "interview_set": 2}


def test_weekly_build_log_sends_one_draft_whose_digits_are_the_in_window_counts(build_log_env):
    _seed_week(_BL_WEEK, stale=5)
    _seed_week({"message_sent": 9})                 # every Telegram message logs this: not outreach
    for i in range(3):
        _seed_thread(f"t{i}", "INTERVIEW" if i else "GENERAL", 1)
    _seed_thread("rej", "REJECTION", 1)             # auto-reject in window: not a reply
    _seed_thread("old", "GENERAL", 10)              # outside the window

    m.scheduled_weekly_build_log_job()

    assert len(build_log_env) == 1
    text = build_log_env[0]
    assert text.startswith("✍️")
    assert sorted(map(int, re.findall(r"\d+", text))) == sorted([37, 23, 11, 6, 4, 2, 3])
    assert pipeline_utils.negative_language_hits(text) == []


def test_weekly_build_log_a_real_zero_week_keeps_its_zero_lines(build_log_env):
    m.scheduled_weekly_build_log_job()

    assert len(build_log_env) == 1
    assert re.findall(r"\d+", build_log_env[0]) == ["0"] * 7


def test_weekly_build_log_unreadable_database_sends_the_alert_and_no_draft(build_log_env, monkeypatch):
    monkeypatch.setattr(m, "DB_PATH", os.path.join(os.path.dirname(_TMP_DB_PATH), "no_such_dir", "x.db"))

    m.scheduled_weekly_build_log_job()

    assert len(build_log_env) == 1
    text = build_log_env[0]
    assert "unavailable" in text.lower()
    assert re.findall(r"\d", text) == []
    assert "Build log:" not in text


def test_weekly_build_log_a_failed_read_leaves_the_key_none_not_zero(build_log_env, monkeypatch):
    import build_log
    _seed_week(_BL_WEEK)

    ok = m.get_weekly_build_log_counts()
    assert set(ok) == set(build_log.BUILD_LOG_KEYS)
    assert ok["applied"] == 4 and ok["replies"] == 0     # a read that finds nothing is a real 0

    class _Boom:
        def __enter__(self):
            raise sqlite3.OperationalError("simulated read failure")

        def __exit__(self, *exc):
            return False
    monkeypatch.setattr(m, "get_db_conn", lambda: _Boom())
    failed = m.get_weekly_build_log_counts()
    assert set(failed) == set(build_log.BUILD_LOG_KEYS)
    assert all(v is None for v in failed.values())


def test_weekly_build_log_posts_to_telegram_only(build_log_env):
    # build_log_env turns requests.post/get into pytest.fail; the job must still complete.
    _seed_week({"applied": 1})
    m.scheduled_weekly_build_log_job()

    assert len(build_log_env) == 1


def test_weekly_build_log_registers_sunday_1800_local_on_the_shared_scheduler(monkeypatch):
    calls = []
    monkeypatch.setattr(m.EMAIL_POLL_SCHEDULER, "add_job", lambda *a, **k: calls.append((a, k)))

    m.start_weekly_build_log()

    assert len(calls) == 1
    args, kwargs = calls[0]
    assert args[0] is m.scheduled_weekly_build_log_job
    assert kwargs["id"] == "weekly_build_log"
    assert kwargs["trigger"] == "cron"
    assert kwargs["day_of_week"] == "sun" and kwargs["hour"] == 18
    assert kwargs["max_instances"] == 1 and kwargs["coalesce"] is True


# ---- /leads/ingest Telegram alert: one message per NEWLY committed lead ----

def test_lead_alert_new_lead_sends_exactly_one_message_with_every_field(leads_env, capture_sent):
    resp = _post_lead(_GOOD_LEAD)

