def test_refer_review_followups_dismiss_never_prints_pending_not_pending(monkeypatch):
    """If the UPDATE misses but the same-transaction read shows pending, say it changed, not 'pending, not pending'."""
    ask_id = _seed_refer_ask(1)

    class _MissingUpdate:
        def __init__(self, conn):
            self._conn = conn

        def execute(self, sql, *a):
            if sql.lstrip().startswith("UPDATE referral_asks SET status = 'dismissed'"):
                return self._conn.execute("UPDATE referral_asks SET status = status WHERE 0")  # rowcount 0
            return self._conn.execute(sql, *a)

        def commit(self):
            return self._conn.commit()

    real = m.get_db_conn
    from contextlib import contextmanager

    @contextmanager
    def wrapped():
        with real() as conn:
            yield _MissingUpdate(conn)

    monkeypatch.setattr(m, "get_db_conn", wrapped)
    reply = m.dismiss_referral_ask(ask_id)
    monkeypatch.setattr(m, "get_db_conn", real)

    assert "pending, not pending" not in reply and "changed while dismissing" in reply and "try again" in reply
    assert _ask_row(ask_id)[0] == "pending"


# ==============================================================================
# TASK-89: years REQUIRED is a hard gate in both filter gates
# ==============================================================================

_YEARS_GATE_REJECT = [
    "4-5 years of experience as a Business Analyst or similar role.",
    "Minimum of 4 years in a similar role",
    "5+ years of experience in operations",
]
_YEARS_GATE_ACCEPT = [
    "3+ years of experience",
    "2-3 years of experience",
    "0-2 years of experience",
    "5+ years of experience preferred",
    "4 years of experience or equivalent education",
    "We have served Michigan families for 40 years. Entry level role.",
]


def test_years_gate_rejects_unit_cases_on_years_required_reject():
    from score_rules import years_required_reject, YEARS_REQUIRED_REJECT_AT
    assert YEARS_REQUIRED_REJECT_AT == 4
    assert years_required_reject("4-5 years of experience as a business analyst.") == 4
    assert years_required_reject("Great team. Minimum of 4 years in a similar role") == 4
    assert years_required_reject("5+ years of experience in operations") == 5
    # The largest requirement wins, and a soft sentence beside it is ignored.
    assert years_required_reject("Needs 4 years of experience. 8 years of experience is a plus.") == 4
    assert years_required_reject("") is None and years_required_reject(None) is None
    for text in _YEARS_GATE_ACCEPT:
        assert years_required_reject(text) is None, text
    assert years_required_reject("Ideally 6 years of experience. Needs 2 years of experience.") is None


def test_years_gate_rejects_through_both_real_filter_gates(monkeypatch, caplog):
    monkeypatch.setattr(m, "is_company_on_cooldown", lambda company: False)
    monkeypatch.setattr(m, "get_applied_crm_companies", lambda: set())
    monkeypatch.setattr(m, "get_filter", lambda key, default=None: {
        "min_salary": 50000, "valid_cities": ["farmington", "detroit"], "title_exclusions": [],
        "company_exclusions": [], "hard_ban_keywords": [], "seniority_exclusions": [],
    }.get(key, default if default is not None else []))
    skill = " Daily reconciliation in Salesforce and Excel."   # keeps the remote core-skill gate satisfied
    strict = {
        "employer_name": "Northwind Co", "job_title": "Operations Analyst",
        "job_city": "Farmington Hills", "job_state": "MI",
        "job_salary": "$70,000", "job_min_salary": 70000, "job_max_salary": 90000,
        "job_apply_link": "https://boards.greenhouse.io/acme/jobs/1",
    }
    # Control: the same jobs with a harmless description pass, so only years can be rejecting below.
    assert m.passes_strict_filter({**strict, "job_description": "Reconciliation in SQL."}) is True
    assert m._passes_remote_filter(_remote_job(job_description="Reconciliation in Salesforce and Excel.")) is True

    for text in _YEARS_GATE_REJECT:
        trace = m.FunnelTrace()
        assert m.passes_strict_filter({**strict, "job_description": text + " SQL."}, trace=trace) is False, text
        assert trace.reasons.get("years_required") == 1, (text, trace.reasons)
        assert m._passes_remote_filter(_remote_job(job_description=text + skill)) is False, text
    for text in _YEARS_GATE_ACCEPT:
        assert m.passes_strict_filter({**strict, "job_description": text + " SQL."}) is True, text
        assert m._passes_remote_filter(_remote_job(job_description=text + skill)) is True, text

    # An unreadable (signup-wall) description is never rejected on years; the short-text line fires.
    teaser = "Sign up to see the full description"
    teaser = (teaser + " " * 120)[:120]
    caplog.set_level("DEBUG")
    assert m.passes_strict_filter({**strict, "job_description": teaser + " SQL"}) is True
    assert any("[YEARS] description too short to read years (" in r.getMessage() for r in caplog.records)


# --- posting_check_at_send: /e, /eh and /letter warn (after the output) when the posting looks closed ---

def _posting_check_env(monkeypatch, command, link, fetch):
    """Drive the real dispatcher for one command with every outbound stubbed. `fetch` replaces
    fetch_job_link_state. Returns (events, fetch_calls, payloads): events is the ordered list of
    ('msg', text) / ('draft',) so a test can assert the warning lands AFTER the draft or letter."""
    events, fetch_calls, payloads = [], [], []
    job = {"employer_name": "Atwell", "job_title": "Operations Analyst", "track": "e",
           "employer_website": "https://atwell.com"}
    if link is not None:
        job["job_apply_link"] = link
    monkeypatch.setattr(m, "resolve_reply_mapping", lambda msg, cid, label: {
        "sheet_uuid": "uuid-pc", "sheet_tab": "Tetiana Cold", "contact_name": "",
        "contact_company": "Atwell"})
    monkeypatch.setattr(m, "get_job_by_sheet_uuid", lambda u: dict(job))
    monkeypatch.setattr(m, "rebuild_job_from_card", lambda j, txt: (j, False))
    monkeypatch.setattr(m, "send_telegram_message", lambda cid, text, **k: events.append(("msg", text)))
    monkeypatch.setattr(m, "send_cover_letter_pdf_async", lambda *a, **k: None)
    monkeypatch.setattr(m, "stage_outreach_draft", lambda *a, **k: events.append(("draft",)))
    monkeypatch.setattr(m, "resolve_target_email", lambda *a, **k: "operations@atwell.com")
    monkeypatch.setattr(m, "resolve_email_waterfall", lambda *a, **k: "dana@atwell.com")
    monkeypatch.setattr(m, "log_email_enrichment_attempt", lambda *a, **k: None)
    monkeypatch.setattr(m, "update_job_target_email", lambda u, e: None)
    monkeypatch.setattr(m, "log_addressed_contact_to_carmen_cold", lambda *a, **k: None)
    monkeypatch.setattr(m, "enqueue_crm_payload", lambda p: payloads.append(p))

    def recorded_fetch(url, timeout=None):
        fetch_calls.append((url, timeout))
        return fetch(url, timeout)

    monkeypatch.setattr(m, "fetch_job_link_state", recorded_fetch)
    _dispatch(command, reply_to_message={"message_id": 42, "text": "card"})
    return events, fetch_calls, payloads


def _fetch_404(url, timeout):
    return (404, url, "", None)


def _fetch_200(url, timeout):
    return (200, url, "Operations Analyst. " + "Responsibilities include reconciling accounts. " * 20, None)


_PC_LINK = "https://boards.greenhouse.io/atwell/jobs/123"


def _pc_warnings(events):
    return [e[1] for e in events if e[0] == "msg" and ("looks closed" in e[1] or "Could not verify" in e[1])]


@pytest.mark.parametrize("command", ["/e", "/eh", "/letter"])
def test_posting_check_at_send_dead_link_warns_after_the_output(monkeypatch, command):
    events, fetch_calls, _ = _posting_check_env(monkeypatch, command, _PC_LINK, _fetch_404)
    first = events[0]
    if command == "/letter":
        assert first[0] == "msg" and "Cover Letter" in first[1]
    else:
        assert first == ("draft",)
    assert "looks closed" in events[-1][1] and "HTTP 404" in events[-1][1]
    assert _PC_LINK in events[-1][1]
    assert len(_pc_warnings(events)) == 1
    assert len(fetch_calls) == 1


@pytest.mark.parametrize("command", ["/e", "/eh", "/letter"])
def test_posting_check_at_send_opaque_host_says_it_could_not_verify(monkeypatch, command):
    link = "https://www.linkedin.com/jobs/view/3912345678"
    events, _, _ = _posting_check_env(monkeypatch, command, link, lambda u, t: (200, u, "x", None))
    warning = events[-1][1]
    assert "Could not verify" in warning and "linkedin.com" in warning


