# ---- TASK-160: /w lists only in-person Michigan roles ----

def test_warm_michigan_closing_message_counts_each_drop_and_lists_only_michigan(monkeypatch):
    roles = [("Operations Analyst Troy", "Troy, MI"), ("Operations Analyst Lansing", "Lansing, MI"),
             ("Operations Analyst Austin", "Austin, TX"), ("Operations Analyst Remote", "Remote"),
             ("Operations Analyst RemoteMI", "Remote - Michigan"), ("Operations Analyst Nowhere", None)]
    h = _summary_harness(monkeypatch, {"Acme Robotics": roles})
    h.filters["valid_cities"] = ["troy", "detroit"]     # Lansing is NOT in the configured list
    text = h.run()
    assert set(h.gemini_calls) == {"Operations Analyst Troy", "Operations Analyst Lansing"}, h.gemini_calls
    assert {r["row_data"][2] for r in h.rows()} == set(h.gemini_calls)
    assert "2 Remote roles dropped" in text, text
    assert "outside Michigan 1" in text and "no Michigan location found 1" in text, text
    assert "out_of_state" not in text and "city_allowlist" not in text, text
    assert "kept with no readable location" not in text, text
    for gone in ("Austin", "Remote", "RemoteMI", "Nowhere"):
        title = f"Operations Analyst {gone}"
        assert not m.is_job_seen_db(m.generate_dedup_hash("Acme Robotics", title)), title


def test_warm_rotation_report_budget_end_names_unscored_company_and_counts(monkeypatch):
    import threading
    names = ["Alpha Labs", "Bravo Labs"]
    h = _screen_harness(monkeypatch, {n: [("Operations Analyst", "Detroit")] for n in names})
    gate = threading.Event()
    real = h._fake_gemini
    done = []

    def slow(job):
        gate.wait(5)
        try:
            return real(job)
        finally:
            done.append(1)

    monkeypatch.setattr(m, "evaluate_job_with_gemini", slow)
    monkeypatch.setattr(m, "WARM_SCREEN_BUDGET_SECONDS", 0)
    try:
        text = h.run()
    finally:
        gate.set()
        for _ in range(100):  # let the released workers finish before the test DB goes away
            if len(done) >= 2:
                break
            threading.Event().wait(0.05)
        threading.Event().wait(0.3)
    assert "Screen: 2 companies picked, 0 finished in" in text, text
    assert "of 0 s." in text
    assert "Budget ended: 2 unscored, first alphabetically: Alpha Labs, Bravo Labs" in text, text
    assert "Cards: 0 from 0 companies." in text
    assert "Boards held back to retry first next run: 2." in text


# ---- TASK-162: warm card honesty ----

def test_warm_card_honesty_boosted_card_shows_base_next_to_final(render_card):
    text = render_card(score=95, score_boost=30, overlap_pct=60)
    assert "<b>95/100</b> (base 65, +30)" in text, text
    assert "low skills match" not in text


def test_warm_card_honesty_unboosted_card_line_is_unchanged(render_card):
    text = render_card(score=80, score_boost=0, overlap_pct=60)
    assert "<b>80/100</b> ·" in text and "base" not in text


def test_warm_card_honesty_negative_boost_prints_base(render_card):
    text = render_card(score=80, score_boost=-5, overlap_pct=60)
    assert "(base 85, -5)" in text


def test_warm_card_honesty_low_skills_flag_only_with_big_boost_and_low_overlap(render_card):
    assert "Skills 15% ⚠ low skills match" in render_card(score=95, score_boost=30, overlap_pct=15)
    assert "low skills match" not in render_card(score=95, score_boost=30, overlap_pct=60)
    assert "low skills match" not in render_card(score=80, score_boost=10, overlap_pct=15)


def test_warm_card_honesty_note_is_old_dates():
    import referral_asks as ra
    today = date(2026, 10, 26)
    assert ra.note_is_old("Analyst at Acme. Connected 2023-03-01 (LinkedIn import)", today) is True
    assert ra.note_is_old("Analyst at Acme. Connected 2026-09-01 (LinkedIn import)", today) is False
    assert ra.note_is_old("Analyst at Acme. Connected 2024-13-40 (LinkedIn import)", today) is False
    assert ra.note_is_old("Active relationship", today) is False
    assert ra.old_note_suffix("Analyst at Acme. Connected 2023-03-01 (LinkedIn import)", today) == \
        " (connected 2023 - may be out of date)"


