def test_hirebase_hook_status_update_raising_still_fetches_and_settles(monkeypatch):
    h = _hirebase_hook_harness(monkeypatch)
    h.feed = [_hirebase_job("Nopeboard Labs", "Operations Analyst", 1)]

    def boom(chat_id, text):
        if "Hirebase" in text:
            raise RuntimeError("telegram down")

    monkeypatch.setattr(m, "send_status_update", boom)
    h.run()
    led = _hirebase_ledger_rows()
    assert len(h.posts) == 2 and len(led) == 2 and led[0][1] == "ok" and led[0][0] == 1, led


# ---- TASK-168: the board-lookup queue drains from one /w ----

def _drain_rows(spec):
    """CRM rows for {company: warm contact count}."""
    rows, i = [], 0
    for company, n in spec.items():
        for _ in range(n):
            rows.append({"company": company, "name": f"Person {i}", "email": f"p{i}@example.com",
                         "note": "Active relationship", "raw_priority": 5, "sheet_uuid": f"u{i}"})
            i += 1
    return rows


def _drain_harness(monkeypatch, spec):
    h = _WarmRadarHarness(monkeypatch, list(spec))
    rows = _drain_rows(spec)
    monkeypatch.setattr(m, "crm_post", lambda payload, **kw: _AskResp({"status": "success", "followups": rows}))
    return h


def _attempted(name):
    with m.get_db_conn() as conn:
        r = conn.execute("SELECT board_attempted_at FROM company_identities WHERE normalized_name = ?",
                         (m.normalize_company_for_match(name),)).fetchone()
    return bool(r and r[0])


def _names(prefix, n):
    return [f"{prefix} Zq{chr(97 + i // 26)}{chr(97 + i % 26)} Works" for i in range(n)]


def test_warm_lookup_drain_one_w_looks_up_every_queued_company(monkeypatch):
    names = _names("Drainone", 45)
    h = _drain_harness(monkeypatch, {n: 1 for n in names})
    h.run()
    assert [n for n in names if not _attempted(n)] == []
    assert not m._WARM_LOOKUPS_IN_FLIGHT


def test_warm_lookup_drain_never_exceeds_the_worker_limit_and_never_repeats_a_company(monkeypatch):
    names = _names("Drainlim", 30)
    h = _drain_harness(monkeypatch, {n: 1 for n in names})
    lock, state, calls = threading.Lock(), {"now": 0, "peak": 0}, []

    def spy(company):
        with lock:
            state["now"] += 1
            state["peak"] = max(state["peak"], state["now"])
            calls.append(company)
        time.sleep(0.01)
        with lock:
            state["now"] -= 1

    monkeypatch.setattr(m, "lookup_warm_company_board", spy)
    h.run()
    assert sorted(calls) == sorted(names) and len(set(calls)) == len(calls)
    assert 1 <= state["peak"] <= m.WARM_RADAR_LOOKUP_WORKERS


def test_warm_lookup_drain_in_progress_does_not_stop_a_second_w_scanning_and_sending(monkeypatch):
    boards = {"Scanned Alpha": [("Operations Analyst", "Detroit")]}
    waiting = _names("Drainwait", 6)
    spec = {"Scanned Alpha": 1, **{n: 1 for n in waiting}}
    h = _summary_harness(monkeypatch, boards, rows=_drain_rows(spec))
    started, release, threads, calls = threading.Event(), threading.Event(), [], []

    def blocked(company):
        calls.append(company)
        started.set()
        release.wait(timeout=10)

    monkeypatch.setattr(m, "lookup_warm_company_board", blocked)

    def spawn(fn):
        t = threading.Thread(target=fn, daemon=True)
        threads.append(t)
        t.start()

    monkeypatch.setattr(m, "_spawn_background", spawn)
    try:
        h.run()
        assert started.wait(timeout=10)
        assert m._WARM_LOOKUPS_IN_FLIGHT == set(waiting)      # the drain is still running
        h.tracked.clear()
        before = len(h.rows())
        text = h.run()                                        # second /w while the drain is blocked
        assert len(h.rows()) > before, text                   # it scanned its board and wrote a card row
        assert any("Operations Analyst" in t for _, t in h.posts)
        assert f"{len(waiting)} more still being checked" in text
    finally:
        release.set()
        for t in threads:
            t.join(timeout=10)
    assert not m._WARM_LOOKUPS_IN_FLIGHT


def test_warm_lookup_drain_big_company_whose_lookup_errored_goes_before_a_fresh_one_person_company(monkeypatch):
    monkeypatch.setattr(m, "WARM_RADAR_LOOKUP_WORKERS", 1)
    big, small = "Drainerr Bigco Works", "Drainerr Solo Works"
    h = _drain_harness(monkeypatch, {small: 1, big: 30})
    m._stamp_board_lookup(big, False)                          # an earlier lookup errored
    assert _attempted(big) and not _attempted(small)
    order = []
    monkeypatch.setattr(m, "lookup_warm_company_board", lambda c: order.append(c))
    h.run()
    assert order == [big, small]


def test_warm_lookup_drain_nobody_under_five_is_looked_up_until_every_five_plus_company_has_finished(monkeypatch):
    bigs = _names("Drainbig", 8)
    smalls = _names("Drainsml", 40)
    spec = {**{n: 5 + i % 3 for i, n in enumerate(bigs)}, **{n: 1 + i % 4 for i, n in enumerate(smalls)}}
    h = _drain_harness(monkeypatch, spec)
    m._stamp_board_lookup(bigs[0], False)                      # one big company already errored once
    lock, finished, violations, calls = threading.Lock(), set(), [], []

    def spy(company):
        with lock:
            calls.append(company)
            if company in smalls and not set(bigs) <= finished:
                violations.append(company)
        time.sleep(0.005)
        with lock:
            finished.add(company)

    monkeypatch.setattr(m, "lookup_warm_company_board", spy)
    h.run()
    assert violations == []
    assert set(calls[:8]) == set(bigs)
    assert sorted(calls) == sorted(bigs + smalls)              # and once they are, the rest are


def test_warm_lookup_drain_a_company_that_keeps_raising_does_not_hold_the_five_plus_set_open(monkeypatch):
    bigs, smalls = _names("Drainraise", 3), _names("Drainsmall", 3)
    h = _drain_harness(monkeypatch, {**{n: 6 for n in bigs}, **{n: 1 for n in smalls}})
    calls = []

    def spy(company):
        calls.append(company)
        if company == bigs[0]:
            raise RuntimeError("always errors")

    monkeypatch.setattr(m, "lookup_warm_company_board", spy)
    h.run()
    assert sorted(calls) == sorted(bigs + smalls) and calls.count(bigs[0]) == 1
    assert not m._WARM_LOOKUPS_IN_FLIGHT


def test_warm_lookup_drain_peak_memory_over_120_companies(monkeypatch):
    import tracemalloc
    names = _names("Drainmem", 120)
    h = _drain_harness(monkeypatch, {n: 1 + i % 7 for i, n in enumerate(names)})
    monkeypatch.setattr(m, "lookup_warm_company_board", lambda c: None)
    tracemalloc.start()
    try:
        h.run()
        _, peak = tracemalloc.get_traced_memory()
    finally:
        tracemalloc.stop()
    print(f"DRAIN_PEAK_BYTES={peak}")
    assert peak < 64 * 1024 * 1024


# ---- TASK-169: company identity records which board system and where the board came from ----

def _board_cols(name):
    with m.get_db_conn() as conn:
        return conn.execute(
            "SELECT ats_slug, workday_board, board_system, board_source FROM company_identities "
            "WHERE normalized_name = ?", (m.normalize_company_for_match(name),)).fetchone()


def _warm_board_system_http(monkeypatch, live_host):
    filters = {"ats_company_slugs": []}
    monkeypatch.setattr(m, "get_filter", lambda key, default=None: list(filters.get(key, default)))
    monkeypatch.setattr(m, "set_filter", lambda key, val: filters.__setitem__(key, list(val)))

    def fake_get(url, timeout=None, **kw):
        if live_host in url:
            return types.SimpleNamespace(status_code=200, json=lambda: {"jobs": [{"id": 1}]})
        return types.SimpleNamespace(status_code=404, json=lambda: {})
    monkeypatch.setattr(m.requests, "get", fake_get)
    return filters


@pytest.mark.parametrize("host,system", [("greenhouse.io", "greenhouse"), ("lever.co", "lever"),
                                         ("ashbyhq.com", "ashby")])
def test_warm_board_system_lookup_records_system_and_own_source(monkeypatch, host, system):
    _warm_board_system_http(monkeypatch, host)
    assert m.lookup_warm_company_board("Acme Robotics") == "acmerobotics"
    assert _board_cols("Acme Robotics") == ("acmerobotics", None, system, "own")


def test_warm_board_system_workday_attach_records_workday_and_own(monkeypatch):
    sent, posts, run = _ats_workday_attach_harness(monkeypatch, _WdResp(200, {"total": 94}))
    run(f"/ats workday {_WD_URL} Plante Moran")
    assert _board_cols("Plante Moran") == (None, "plantemoran/wd5/PlanteMoran", "workday", "own")


def test_warm_board_system_no_probe_path_stays_null_and_reupsert_does_not_clear(monkeypatch):
    filters = _warm_board_system_http(monkeypatch, "greenhouse.io")
    filters["ats_company_slugs"] = ["acmerobotics"]  # already tracked: no board answers, system unknown
    assert m.lookup_warm_company_board("Acme Robotics") == "acmerobotics"
    assert _board_cols("Acme Robotics") == ("acmerobotics", None, None, None)
    m.upsert_company_identity("Acme Robotics", board_system="lever", board_source="own")
    assert m.lookup_warm_company_board("Acme Robotics") == "acmerobotics"
    m.upsert_company_identity("Acme Robotics", ats_slug="acmerobotics")
    assert _board_cols("Acme Robotics") == ("acmerobotics", None, "lever", "own")


def test_warm_board_system_bought_source_is_not_overwritten_by_a_refind():
    m.upsert_company_identity("Paid Co", ats_slug="paidco", board_system="lever")
    with m.get_db_conn() as conn:
        conn.execute("UPDATE company_identities SET board_source = 'bought' WHERE normalized_name = ?",
                     (m.normalize_company_for_match("Paid Co"),))
        conn.commit()
    m.upsert_company_identity("Paid Co", ats_slug="paidco", board_system="lever", board_source="own")
    assert _board_cols("Paid Co")[3] == "bought"


def test_warm_board_system_list_and_switch_off_touch_only_bought_rows():
    m.upsert_company_identity("Own Co", ats_slug="ownco", board_system="greenhouse", board_source="own")
    m.upsert_company_identity("Bought Co", ats_slug="boughtco", board_system="ashby")
    m.upsert_company_identity("Bought Wd", workday_board="bw/wd1/Site", board_system="workday")
    m.upsert_company_identity("Unrecorded Co", ats_slug="unrecorded")
    with m.get_db_conn() as conn:
        conn.execute("UPDATE company_identities SET board_source = 'bought' WHERE normalized_name IN (?, ?)",
                     (m.normalize_company_for_match("Bought Co"), m.normalize_company_for_match("Bought Wd")))
        conn.commit()
    before_own, before_unrec = _board_cols("Own Co"), _board_cols("Unrecorded Co")
    assert m.list_bought_boards() == [("Bought Co", "boughtco", "ashby"), ("Bought Wd", "bw/wd1/Site", "workday")]
    assert m.switch_off_bought_boards() == 2
    assert _board_cols("Bought Co") == (None, None, None, "bought")
    assert _board_cols("Bought Wd") == (None, None, None, "bought")
    assert _board_cols("Own Co") == before_own == ("ownco", None, "greenhouse", "own")
    assert _board_cols("Unrecorded Co") == before_unrec
    assert m.switch_off_bought_boards() == 0
